const STORAGE='dachun-select-demo-v3';
function freshState(){return {member:true,points:60000,cart:{},favorites:[],orders:[],redeemed:[],reviews:{},ledger:[{title:'演示积分初始化',amount:60000,date:'体验账户'}]}}
function loadState(){try{const saved=JSON.parse(localStorage.getItem(STORAGE));return saved&&typeof saved==='object'?{...freshState(),...saved}:freshState()}catch{return freshState()}}
let state=loadState(),page='shop',category='全部',sideCategory='厨房',query='',sort='精选',currentProduct=null,detailQuantity=1,selectedCart=new Set(Object.keys(state.cart).map(Number)),checkoutItems=[],address='演示住址 A',modalAction=null,reviewProduct=null,toastTimer;
const $=selector=>document.querySelector(selector),$$=selector=>document.querySelectorAll(selector);
function save(){localStorage.setItem(STORAGE,JSON.stringify(state))}
function icon(name){return `<svg class="icon"><use href="#i-${name}"/></svg>`}
function money(number){const rounded=Math.round(number*10)/10;return '¥'+(Number.isInteger(rounded)?rounded:rounded.toFixed(1))}
function memberPrice(product){return Math.round(product.price*9)/10}
function unitPrice(product){return state.member?memberPrice(product):product.price}
function expectedPoints(product){return Math.floor(memberPrice(product)/10)}
function escapeHtml(value){return String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function product(id){return PRODUCTS.find(p=>p.id===Number(id))}
function showToast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2000)}
function syncLock(){const busy=$('#detailScreen').classList.contains('open')||$('#checkoutScreen').classList.contains('open')||$('#cartSheet').classList.contains('open')||$('#confirmModal').classList.contains('open')||$('#reviewModal').classList.contains('open');document.body.style.overflow=busy?'hidden':'';$('#overlay').classList.toggle('open',$('#cartSheet').classList.contains('open')||$('#confirmModal').classList.contains('open')||$('#reviewModal').classList.contains('open'))}
function showConfirm(title,body,button,callback){modalAction=callback;$('#modalTitle').textContent=title;$('#modalBody').textContent=body;$('#modalConfirm').textContent=button;$('#confirmModal').classList.add('open');syncLock()}
function closeConfirm(){$('#confirmModal').classList.remove('open');modalAction=null;syncLock()}
function renderHeader(){$('#cartBadge').textContent=Object.values(state.cart).reduce((a,b)=>a+b,0);$('#cartBadge').hidden=!Number($('#cartBadge').textContent);$('#searchBar').hidden=page!=='shop';$('#clearSearch').hidden=!query}
function renderCategories(){$('#categoryBar').innerHTML=['全部','厨房','清洁','居住','学习'].map(c=>`<button class="category ${category===c?'active':''}" data-action="category" data-category="${c}">${{全部:'全部好物',厨房:'厨房生活',清洁:'居家清洁',居住:'居住品质',学习:'学习办公'}[c]}</button>`).join('');$('#productCount').textContent=query||category!=='全部'?`${visibleProducts().length} 件符合当前选择的好物`:'四个生活场景 · 10 件示例好物'}
function visibleProducts(){let items=PRODUCTS.filter(p=>(category==='全部'||p.cat===category)&&(!query||(p.name+p.sub+p.why+p.cat).includes(query)));if(sort==='价格升序')items.sort((a,b)=>a.price-b.price);if(sort==='价格降序')items.sort((a,b)=>b.price-a.price);return items}
function renderShop(){renderCategories();const focused=category!=='全部'||query;$('#brandStrip').hidden=!!focused;$('#weekly').hidden=!!focused;$('#listTitle').textContent=query?'搜索结果':category==='全部'?'本周真选':{厨房:'厨房生活',清洁:'居家清洁',居住:'居住品质',学习:'学习办公'}[category];$('#listSub').textContent=query?`找到 ${visibleProducts().length} 件相关好物`:'每件商品，都要说清为什么选它';$('#sortButton').innerHTML=`${sort==='精选'?'为你精选':sort} ${icon('chevron')}`;const items=visibleProducts();$('#productGrid').innerHTML=items.length?items.map(p=>`<article class="product-card"><button class="product-image" data-action="detail" data-id="${p.id}" aria-label="查看${p.name}详情"><img src="${p.img}" alt="${p.name}" loading="lazy" decoding="async"><span>${p.tag}</span></button><div class="product-info"><button class="product-name" data-action="detail" data-id="${p.id}">${p.name}</button><div class="product-reason">${p.why}</div><div class="price-row"><span class="price"><small>¥</small>${p.price}</span><button class="round-add" data-action="add" data-id="${p.id}" aria-label="加入购物袋：${p.name}">${icon('plus')}</button></div><div class="product-points">会员价 ${money(memberPrice(p))} · 约 +${expectedPoints(p)} 积分</div></div></article>`).join(''):'<div class="empty">暂时没有找到相关好物，换个词试试。</div>'}
function renderCategoryPage(){const names={厨房:'厨房生活',清洁:'居家清洁',居住:'居住品质',学习:'学习办公'};$('#categorySide').innerHTML=Object.keys(names).map(c=>`<button class="${sideCategory===c?'active':''}" data-action="side-category" data-category="${c}" aria-current="${sideCategory===c?'true':'false'}">${names[c]}</button>`).join('');const items=PRODUCTS.filter(p=>p.cat===sideCategory);$('#categoryContentHead').innerHTML=`<small>PRODUCT SELECTION · ${String(items.length).padStart(2,'0')}</small><h2>${names[sideCategory]}</h2><p>从真实日常出发，选用得上的好物。</p>`;$('#categoryList').innerHTML=items.map(p=>`<article class="category-item"><button class="category-photo" data-action="detail" data-id="${p.id}" aria-label="查看${p.name}详情"><img src="${p.img}" alt="${p.name}" loading="lazy" decoding="async"></button><div class="category-item-info"><button class="category-item-name" data-action="detail" data-id="${p.id}">${p.name}</button><p>${p.why}</p><div class="category-item-bottom"><span><b>${money(p.price)}</b><small>会员 ${money(memberPrice(p))} · +${expectedPoints(p)} 积分</small></span><button class="round-add" data-action="add" data-id="${p.id}" aria-label="加入购物袋：${p.name}">${icon('plus')}</button></div></div></article>`).join('')}
function renderPoints(){const rewards=REWARDS.map(r=>`<article class="reward-card"><div class="reward-art">${r.mark}</div><div class="reward-copy"><strong>${r.name}</strong><p>${r.desc}</p><div class="reward-bottom"><b>${r.points.toLocaleString()} 积分</b><button class="mini-btn" data-action="redeem" data-id="${r.id}">立即兑换</button></div></div></article>`).join('');$('#page-points').innerHTML=`<div class="page-kicker">GROWTH POINTS</div><h1 class="page-title">把生活消费，变成成长</h1><p class="page-sub">买的是生活用品，积的是成长权益。积分用于大春课程、AI 与幸福服务。</p><div class="balance-card"><small>我的成长积分 · 演示账户</small><strong>${state.points.toLocaleString()}</strong><p>会员每实付 10 元获得 1 积分，积分不返现</p><button data-action="page" data-page="shop">去逛真选商品 →</button></div><p class="point-rule">为了体验全部兑换流程，演示账户预置 60,000 积分。正式积分规则以平台公示为准。</p><div class="section-head"><div><h2>大春权益兑换</h2><small>把选择延伸到家庭学习与实践</small></div></div><div class="reward-list">${rewards}</div><div class="section-head"><div><h2>积分明细</h2><small>获得与兑换都看得见</small></div></div><ul class="ledger">${state.ledger.slice().reverse().map(l=>`<li><div>${escapeHtml(l.title)}<small>${escapeHtml(l.date)}</small></div><b class="${l.amount<0?'minus':''}">${l.amount>0?'+':''}${l.amount.toLocaleString()}</b></li>`).join('')}</ul><div class="section-head"><div><h2>我的兑换</h2><small>仅为演示凭证</small></div></div>${state.redeemed.length?state.redeemed.slice().reverse().map(x=>`<div class="order-card"><div class="order-top"><span>${escapeHtml(x.date)}</span><b>已兑换</b></div><strong style="font-size:13px">${escapeHtml(x.name)}</strong><div style="font-size:11px;color:var(--muted);margin-top:5px">演示兑换凭证 · ${x.points.toLocaleString()} 积分</div></div>`).join(''):'<p class="page-sub">还没有兑换记录，选一个喜欢的权益开始体验。</p>'}`}
function renderMemberCard(){return `<div class="member-card"><div class="seal">真</div><small>DA CHUN SELECT · ANNUAL MEMBER</small><strong>${state.member?'大春真选 · 年度会员':'大春真选 · 家庭生活卡'}</strong><div class="card-bottom"><span>${state.member?'会员状态 · 已开通':'会员状态 · 待开通'}</span><span>¥69 / 365 天</span></div><button data-action="flip-card">${state.cardBack?'看正面':'看权益'} ↗</button></div>`}
function renderAccount(){const card=state.cardBack?`<div class="member-card"><div class="seal">真</div><small>MEMBER BENEFITS</small><strong>少买错 · 用得好 · 能成长</strong><div class="card-bottom"><span>商品 9 折 · 成长积分</span><span>课程 · 沙龙</span></div><button data-action="flip-card">看正面 ↗</button></div>`:renderMemberCard();$('#page-account').innerHTML=`<div class="page-kicker">MY DA CHUN</div><h1 class="page-title">我的大春真选</h1><p class="page-sub">一张卡，记录家庭生活里更好的选择。</p>${card}<div class="benefit-grid"><div class="benefit"><b>商品 9 折</b><span>会员价明示在商品页</span></div><div class="benefit"><b>成长积分</b><span>实付 10 元得 1 积分</span></div><div class="benefit"><b>专栏体验</b><span>指定生活与家庭课程</span></div><div class="benefit"><b>幸福沙龙</b><span>3 次沙龙体验权益</span></div></div><div style="margin-top:14px"><button class="full-btn" style="width:100%" data-action="${state.member?'page':'join-member'}" ${state.member?'data-page="points"':''}>${state.member?'查看我的积分与兑换':'模拟开通年度会员 · ¥69'}</button></div><div class="section-head"><h2>我的服务</h2></div><div class="account-list"><button data-action="page" data-page="orders">我的订单 <small>${state.orders.length} 笔 →</small></button><button data-action="page" data-page="favorites">我的收藏 <small>${state.favorites.length} 件 →</small></button><button data-action="page" data-page="points">积分与兑换 <small>${state.points.toLocaleString()} 分 →</small></button><button data-action="meaning">大春真选之道 <small>认识六个“真” →</small></button></div><button class="identity-switch" data-action="toggle-identity">${state.member?'切换普通用户视角（演示）':'切换回会员视角（演示）'}</button><button class="identity-switch" data-action="reset" style="float:right">重置演示数据</button>`}
function renderMeaning(){$('#page-meaning').innerHTML=`<div class="view-head"><button data-action="page" data-page="shop" aria-label="返回商城">${icon('left')}</button><h1>大春真选之道</h1></div><div class="meaning-hero"><img src="assets/dachun-life-hero-v2.jpg" alt="晨光里，妈妈陪孩子享用早餐"><div class="meaning-hero-caption"><small>DA CHUN SELECT · A BETTER EVERYDAY</small><h2>把好生活<br>选回家</h2></div></div><div class="meaning-intro"><span>写给每一个认真过日子的家</span><h2>好的生活，<br>藏在被好好选择的日常里。</h2><p>一顿安心的饭，一件顺手的物，家人围坐的一点时间。我们希望这些微小而真实的美好，不必靠运气遇见。</p><p>大春之道，让家庭懂得更好的生活；大春真选，让这份懂得变成每天都在使用的好东西。</p></div><div class="meaning-promise"><div><em>01 / 少买错</em><b>先想清楚，再带回家</b><p>从真实需求出发，讲明白适合谁，也说清不适合谁。</p></div><div><em>02 / 用得好</em><b>让好物融入日常</b><p>不只展示商品，也分享选法、用法与需要留意的细节。</p></div><div><em>03 / 能成长</em><b>让每次选择都有回响</b><p>日常消费积累成长积分，走向课程、AI 与幸福服务。</p></div></div><div class="meaning-section-head"><small>THE SIX TRUTHS · 六真准则</small><h2>真选重在真。</h2><p>每一件进入家里的东西，都值得被认真问一问。</p></div><div class="truth-list">${TRUTHS.map((t,i)=>`<div class="truth-row"><em>0${i+1}</em><div><b>${t[0]}</b><p>${t[1]}</p></div></div>`).join('')}</div><div class="meaning-member"><div class="meaning-member-top"><small>DA CHUN SELECT · FAMILY MEMBERSHIP</small><span>家庭年度会员</span></div><h2>把更好的选择，<br>留给一家人的每一天。</h2><p>一张家庭生活卡，陪你少买错、用得好，也把日常选择积累成成长。</p><div class="meaning-member-benefits"><span>商品 9 折</span><span>成长积分</span><span>指定专栏体验</span><span>3 次幸福沙龙</span></div><div class="meaning-member-bottom"><div><strong>¥69</strong><small>/ 365 天 · 演示权益</small></div><button class="full-btn" data-action="page" data-page="account">${state.member?'查看我的会员卡':'了解会员权益'} →</button></div></div><div class="meaning-ending"><p>愿每一次带回家的选择，<br>都让生活温柔一点、笃定一点。</p><button data-action="page" data-page="category">去看看真选好物 →</button></div><p class="fineprint">商品与会员权益均为设计演示，请以正式上线公示为准</p>`}
function renderOrders(){const cards=state.orders.length?state.orders.slice().reverse().map(o=>`<article class="order-card"><div class="order-top"><span>订单 ${o.id} · ${escapeHtml(o.date)}</span><b>${escapeHtml(o.status)}</b></div>${o.items.map(i=>{const p=product(i.id);return `<div class="order-item"><img src="${p.img}" alt="" loading="lazy" decoding="async"><span>${p.name}<br>× ${i.qty}</span></div>`}).join('')}<div class="order-total"><span>实付 ${money(o.total)} · 获得 ${o.points} 积分</span><strong>${o.member?'会员价':'普通价'}</strong></div><div class="order-actions">${o.status==='待收货'?`<button data-action="receive" data-id="${o.id}">模拟收货</button>`:''}${o.status==='已完成'?`<button data-action="review" data-id="${o.items[0].id}" data-order="${o.id}">记录使用</button><button data-action="aftersale" data-id="${o.id}">申请售后</button>`:''}${o.status==='售后处理中'?'<button disabled>处理中</button>':''}</div></article>`).join(''):'<p class="page-sub" style="padding:30px 0">还没有订单。挑一件好物，体验完整购买流程。</p>';$('#page-orders').innerHTML=`<div class="view-head"><button data-action="page" data-page="account" aria-label="返回我的">${icon('left')}</button><h1>我的订单</h1></div>${cards}${!state.orders.length?'<button class="full-btn" data-action="page" data-page="shop">去逛商城</button>':''}`}
function renderFavorites(){const favorites=PRODUCTS.filter(p=>state.favorites.includes(p.id));$('#page-favorites').innerHTML=`<div class="view-head"><button data-action="page" data-page="account" aria-label="返回我的">${icon('left')}</button><h1>我的收藏</h1></div><div class="product-grid">${favorites.length?favorites.map(p=>`<article class="product-card"><button class="product-image" data-action="detail" data-id="${p.id}"><img src="${p.img}" alt="${p.name}" loading="lazy" decoding="async"></button><div class="product-info"><button class="product-name" data-action="detail" data-id="${p.id}">${p.name}</button><div class="price-row"><span class="price">${money(p.price)}</span><button class="round-add" data-action="add" data-id="${p.id}" aria-label="加入购物袋">${icon('plus')}</button></div></div></article>`).join(''):'<div class="empty">还没有收藏，喜欢的好物可以先存起来。</div>'}</div>`}
function renderAll(){renderHeader();renderShop();renderCategoryPage();renderPoints();renderAccount();renderMeaning();renderOrders();renderFavorites();renderCart();if(currentProduct)renderDetail();if($('#checkoutScreen').classList.contains('open'))renderCheckout()}
function navigate(target){page=target;$$('.page').forEach(el=>el.hidden=el.id!=='page-'+target);$$('.nav-btn').forEach(el=>el.classList.toggle('active',el.dataset.page===target||(target==='meaning'&&el.dataset.page==='shop')||(['orders','favorites'].includes(target)&&el.dataset.page==='account')));renderAll();window.scrollTo({top:0,behavior:'smooth'})}
function openDetail(id){currentProduct=product(id);detailQuantity=1;renderDetail();$('#detailScroll').scrollTop=0;$('#detailScreen').classList.add('open');syncLock()}
function renderDetail(){const p=currentProduct;if(!p)return;$('#detailImage').src=p.img;$('#detailImage').alt=p.name;$('#detailTag').textContent=p.tag;$('#detailQty').textContent=detailQuantity;$('#favoriteCurrent').style.color=state.favorites.includes(p.id)?'var(--rust)':'var(--green)';let reviews=(state.reviews[p.id]||[]).map(r=>`<div class="review">${escapeHtml(r.text)}<br><span style="font-size:10px;color:#9da79e">${escapeHtml(r.date)} · 我的使用记录</span></div>`).join('');$('#detailBody').innerHTML=`<h1>${p.name}</h1><p class="detail-sub">${p.sub}</p><div class="detail-price-row"><span class="price">${money(p.price)}</span><small>会员价 ${money(memberPrice(p))}</small></div><button class="points-pill" data-action="page" data-page="points">会员购买预计得 ${expectedPoints(p)} 积分 · 去看能换什么 →</button><section class="detail-section"><div class="editor-note"><small>真选观察 · 本周主推的选品方式</small><h3>为什么选它？</h3><p>${p.why}</p></div></section><section class="detail-section"><h2>它解决什么问题</h2><p>${p.problem}</p></section>${p.learn?`<section class="detail-section"><h2>一条实用的生活知识</h2><p>${p.learn}</p>${p.source?`<p class="source">参考：<a href="${p.source}" target="_blank" rel="noopener">USDA 食品安全建议 ↗</a></p>`:''}</section>`:''}<section class="detail-section"><h2>每件商品，回答六个“真”</h2><div class="truth-mini"><div><b>真需求</b><span>${p.problem}</span></div><div><b>真品质</b><span>${p.quality}</span></div><div><b>真价格</b><span>公开价 ${money(p.price)}；会员价 ${money(memberPrice(p))}。</span></div><div><b>真使用</b><span>${p.use}</span></div><div><b>真分享</b><span>${reviews?'查看下方真实使用记录。':'目前尚无真实用户使用记录，欢迎购后反馈。'}</span></div><div><b>真负责</b><span>在订单页可发起售后，处理记录留在订单中。</span></div></div><div class="caveat">先说不适合：${p.caveat}</div></section><section class="detail-section"><h2>适合哪些家庭</h2><p>${p.fit}</p></section><section class="detail-section"><h2>真实使用记录</h2><div class="review-list">${reviews||'<p>暂无使用反馈。我们不会填充虚构评价。</p>'}</div></section><section class="detail-section"><h2>配送与售后</h2><p>当前为可交互设计演示。配送、商品参数与售后时效需在正式上架时公示，演示订单可在“我的订单”里体验售后入口。</p></section>`}
function closeDetail(){$('#detailScreen').classList.remove('open');syncLock()}
function cartQuantity(){return Object.values(state.cart).reduce((a,b)=>a+b,0)}
function addToCart(id,qty=1){state.cart[id]=(state.cart[id]||0)+qty;selectedCart.add(id);save();renderAll();showToast('已加入购物袋')}
function renderCart(){const ids=Object.keys(state.cart).map(Number).filter(id=>state.cart[id]>0);$('#cartCount').textContent=cartQuantity();$('#cartBody').innerHTML=ids.length?ids.map(id=>{const p=product(id);return `<div class="cart-line"><input class="check" type="checkbox" data-cart-id="${id}" aria-label="选择${p.name}" ${selectedCart.has(id)?'checked':''}><img src="${p.img}" alt="" loading="lazy" decoding="async"><div><strong>${p.name}</strong><span class="price">${money(unitPrice(p))}</span><div class="quantity"><button data-action="cart-qty" data-id="${id}" data-step="-1" aria-label="减少数量">−</button><span>${state.cart[id]}</span><button data-action="cart-qty" data-id="${id}" data-step="1" aria-label="增加数量">＋</button></div></div></div>`}).join(''):'<p class="page-sub" style="text-align:center;padding:35px 0">购物袋还是空的，去挑一件适合家里的好物。</p>';const chosen=ids.filter(id=>selectedCart.has(id));const total=Math.round(chosen.reduce((sum,id)=>sum+unitPrice(product(id))*state.cart[id],0)*10)/10;$('#cartTotal').innerHTML=`<small>已选 ${chosen.reduce((n,id)=>n+state.cart[id],0)} 件</small>${money(total)}`}
function openCart(){$('#cartSheet').classList.add('open');renderCart();syncLock()}
function closeSheet(){$('#cartSheet').classList.remove('open');syncLock()}
function selectedItems(){return Object.keys(state.cart).map(Number).filter(id=>state.cart[id]>0&&selectedCart.has(id)).map(id=>({id,qty:state.cart[id]}))}
function startCheckout(){checkoutItems=selectedItems();if(!checkoutItems.length){showToast('请先选择要结算的商品');return}closeSheet();$('#checkoutScreen').classList.add('open');renderCheckout();syncLock()}
function checkoutAmount(){return Math.round(checkoutItems.reduce((sum,i)=>sum+unitPrice(product(i.id))*i.qty,0)*10)/10}
function renderCheckout(){const items=checkoutItems.map(i=>{const p=product(i.id);return `<div class="checkout-item"><img src="${p.img}" alt="" loading="lazy" decoding="async"><span>${p.name} × ${i.qty}</span><b style="font-size:12px">${money(unitPrice(p)*i.qty)}</b></div>`}).join('');const original=checkoutItems.reduce((sum,i)=>sum+product(i.id).price*i.qty,0),total=checkoutAmount(),earned=state.member?Math.floor(total/10):0;$('#checkoutBody').innerHTML=`<div class="checkout-box"><h3>演示收货信息</h3><div class="fake-address"><button data-action="address" data-id="演示住址 A" class="${address==='演示住址 A'?'active':''}">演示住址 A</button><button data-action="address" data-id="演示住址 B" class="${address==='演示住址 B'?'active':''}">演示住址 B</button></div><p class="source" style="margin-bottom:0">不会收集真实姓名、电话或住址。</p></div><div class="checkout-box"><h3>商品清单</h3>${items}</div><div class="checkout-box"><h3>费用与成长</h3><div class="summary-line"><span>商品金额</span><strong>${money(original)}</strong></div><div class="summary-line discount"><span>年度会员 9 折</span><strong>${state.member?'−'+money(original-total):'未开通'}</strong></div><div class="summary-line"><span>演示配送</span><strong>¥0</strong></div><div class="summary-line"><span>本单可得积分</span><strong>+${earned}</strong></div></div>${!state.member?'<div class="story-teaser" style="margin-top:0"><small>会员权益</small><h3>加入后，本单享 9 折</h3><button data-action="join-member">模拟开通年度会员 · ¥69 →</button></div>':''}<p class="fineprint">点击下单只生成本机演示订单，不会产生实际支付或发货。</p>`;$('#checkoutTotal').innerHTML=`<small>合计支付 · 演示</small>${money(total)}`}
function closeCheckout(){$('#checkoutScreen').classList.remove('open');syncLock();openCart()}
function placeOrder(){if(!checkoutItems.length)return;const total=checkoutAmount(),earned=state.member?Math.floor(total/10):0;const order={id:String(Date.now()).slice(-8),date:new Date().toLocaleString('zh-CN',{hour12:false}),items:checkoutItems.map(i=>({...i})),total,points:earned,member:state.member,status:'待收货',address};state.orders.push(order);state.points+=earned;if(earned)state.ledger.push({title:'订单 '+order.id+' 消费积分',amount:earned,date:order.date});for(const item of checkoutItems){delete state.cart[item.id];selectedCart.delete(item.id)}checkoutItems=[];save();$('#checkoutScreen').classList.remove('open');$('#detailScreen').classList.remove('open');navigate('orders');syncLock();showToast(`演示订单已生成 · 获得 ${earned} 积分`)}
function redeemReward(id){const reward=REWARDS.find(r=>r.id===id);if(!reward)return;if(!state.member){showConfirm('先开通会员','成长积分兑换面向真选会员。','查看会员卡',()=>navigate('account'));return}if(state.points<reward.points){showToast('积分不足，继续通过真实消费积累');return}showConfirm('兑换 '+reward.name,`将使用 ${reward.points.toLocaleString()} 积分。兑换后生成本机演示凭证，不会开通真实课程或服务。`,'确认兑换',()=>{state.points-=reward.points;const date=new Date().toLocaleString('zh-CN',{hour12:false});state.redeemed.push({id:reward.id,name:reward.name,points:reward.points,date});state.ledger.push({title:'兑换 '+reward.name,amount:-reward.points,date});save();renderAll();showToast('兑换成功，已记入我的兑换')})}
function joinMember(){showConfirm('开通年度会员', '演示开通 ¥69 / 365 天会员，商品 9 折、实付积分、课程与沙龙权益可立即体验；不会产生真实扣款。','模拟开通',()=>{state.member=true;save();renderAll();showToast('年度会员已开通（演示）')})}
function toggleFavorite(){if(!currentProduct)return;const id=currentProduct.id;state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];save();renderAll();showToast(state.favorites.includes(id)?'已收藏':'已取消收藏')}
function reviewOrder(orderId,productId){reviewProduct={orderId,productId};$('#reviewInput').value='';$('#reviewModal').classList.add('open');syncLock()}
function saveReview(){const text=$('#reviewInput').value.trim();if(text.length<5){showToast('请至少写下 5 个字的真实使用感受');return}const id=reviewProduct.productId;state.reviews[id]=state.reviews[id]||[];state.reviews[id].push({text,date:new Date().toLocaleDateString('zh-CN')});save();$('#reviewModal').classList.remove('open');renderAll();syncLock();showToast('使用记录已保存')}
document.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(!el)return;const action=el.dataset.action,id=el.dataset.id;if(action==='page'){closeDetail();navigate(el.dataset.page)}else if(action==='side-category'){sideCategory=el.dataset.category;renderCategoryPage()}else if(action==='meaning'){closeDetail();navigate('meaning')}else if(action==='category'){category=el.dataset.category;renderShop();$('#categoryBar').scrollIntoView({behavior:'smooth',block:'start'})}else if(action==='sort'){sort=sort==='精选'?'价格升序':sort==='价格升序'?'价格降序':'精选';renderShop()}else if(action==='detail'){openDetail(id)}else if(action==='close-detail'){closeDetail()}else if(action==='add'){addToCart(Number(id))}else if(action==='detail-qty'){detailQuantity=Math.max(1,Math.min(20,detailQuantity+Number(el.dataset.step)));$('#detailQty').textContent=detailQuantity}else if(action==='add-current'){addToCart(currentProduct.id,detailQuantity)}else if(action==='buy-current'){addToCart(currentProduct.id,detailQuantity);openCart()}else if(action==='favorite-current'){toggleFavorite()}else if(action==='cart'){openCart()}else if(action==='close-sheet'){closeSheet()}else if(action==='close-top'){if($('#confirmModal').classList.contains('open'))closeConfirm();else if($('#reviewModal').classList.contains('open')){$('#reviewModal').classList.remove('open');syncLock()}else closeSheet()}else if(action==='cart-qty'){const key=Number(id);state.cart[key]=Math.max(0,(state.cart[key]||0)+Number(el.dataset.step));if(!state.cart[key]){delete state.cart[key];selectedCart.delete(key)}save();renderAll()}else if(action==='checkout'){startCheckout()}else if(action==='close-checkout'){closeCheckout()}else if(action==='address'){address=id;renderCheckout()}else if(action==='place-order'){placeOrder()}else if(action==='redeem'){redeemReward(id)}else if(action==='modal-cancel'){closeConfirm()}else if(action==='modal-confirm'){const callback=modalAction;closeConfirm();if(callback)callback()}else if(action==='join-member'){joinMember()}else if(action==='flip-card'){state.cardBack=!state.cardBack;renderAccount()}else if(action==='toggle-identity'){state.member=!state.member;save();renderAll();showToast(state.member?'已切换至会员视角':'已切换至普通用户视角')}else if(action==='reset'){showConfirm('重置演示数据','将清除本机的购物袋、订单、收藏、积分兑换和使用记录，恢复到初始体验账户。','确认重置',()=>{state=freshState();selectedCart.clear();save();navigate('shop');showToast('演示数据已重置')})}else if(action==='receive'){const order=state.orders.find(o=>o.id===id);if(order){order.status='已完成';save();renderAll();showToast('演示订单已完成')}}else if(action==='aftersale'){showConfirm('申请售后','将该演示订单标记为“售后处理中”，用于体验处理入口。','提交申请',()=>{const order=state.orders.find(o=>o.id===id);if(order){order.status='售后处理中';save();renderAll();showToast('售后申请已提交（演示）')}})}else if(action==='review'){reviewOrder(el.dataset.order,Number(id))}else if(action==='review-cancel'){$('#reviewModal').classList.remove('open');syncLock()}else if(action==='review-save'){saveReview()}});
document.addEventListener('change',event=>{if(event.target.matches('[data-cart-id]')){const id=Number(event.target.dataset.cartId);if(event.target.checked)selectedCart.add(id);else selectedCart.delete(id);renderCart()}});
$('#searchInput').addEventListener('input',event=>{query=event.target.value.trim();renderHeader();renderShop()});$('#clearSearch').addEventListener('click',event=>{event.preventDefault();$('#searchInput').value='';query='';renderHeader();renderShop();$('#searchInput').focus()});document.addEventListener('keydown',event=>{if(event.key==='Escape'){if($('#confirmModal').classList.contains('open'))closeConfirm();else if($('#reviewModal').classList.contains('open')){$('#reviewModal').classList.remove('open');syncLock()}else if($('#cartSheet').classList.contains('open'))closeSheet();else if($('#checkoutScreen').classList.contains('open'))closeCheckout();else if($('#detailScreen').classList.contains('open'))closeDetail()}});
renderAll();
